//! ADM1 CSTR parity against `src/sim/adm1.ts`.
//!
//! Fixture: seed digester feed, V=1000 m3, Q=100 m3/h, 0.5 h steps, 48 h.
//! Golden generated by the TypeScript oracle on 2026-11-25.

use aquapilot_core::adm1::{Component, Output, PARAMS, State, StepOptions, empty_state, step_adm1};

const EXPECTED: [f64; 27] = [
    3.4725727399359223,
    0.5,
    9.156819525826922,
    4.732029774300728,
    4.732029774300728,
    19.514997594597652,
    33.958959607249064,
    0.0005,
    32.25860787057265,
    71.66910474129993,
    50.0,
    20.144370633415388,
    99.48284506006769,
    50.0,
    50.0,
    30.0,
    2.585781884297829,
    2.5542778847638674,
    1.0389067453041765,
    4.992915203832443,
    4.974821718587979,
    9.943320844986317,
    17.86899630157432,
    50.0,
    0.0003958333333333333,
    22.1354394575385,
    28.33089525870004,
];

fn feed() -> State {
    let mut s = empty_state();
    for (c, v) in [
        (Component::SSu, 20.0),
        (Component::SAa, 10.0),
        (Component::SFa, 5.0),
        (Component::SVa, 5.0),
        (Component::SBu, 5.0),
        (Component::SPro, 5.0),
        (Component::SAc, 20.0),
        (Component::SH2, 0.01),
        (Component::SCh4, 0.1),
        (Component::SIC, 100.0),
        (Component::SIN, 50.0),
        (Component::SI, 20.0),
        (Component::Xc, 100.0),
        (Component::Xch, 50.0),
        (Component::Xpr, 50.0),
        (Component::Xli, 30.0),
        (Component::Xsu, 10.0),
        (Component::Xaa, 10.0),
        (Component::Xfa, 5.0),
        (Component::Xc4, 5.0),
        (Component::Xpro, 5.0),
        (Component::Xac, 10.0),
        (Component::Xh2, 5.0),
        (Component::XI, 50.0),
    ] {
        s.set(c, v);
    }
    s
}

#[test]
fn adm1_48h_matches_ts_golden() {
    let inf = feed();
    let mut state = inf;
    let mut last: Output = step_adm1(
        &state,
        &inf,
        &PARAMS,
        StepOptions {
            volume: 1000.0,
            flow: 100.0,
            dt_hours: 0.5,
        },
    );
    state = last.state;
    for _ in 1..96 {
        last = step_adm1(
            &state,
            &inf,
            &PARAMS,
            StepOptions {
                volume: 1000.0,
                flow: 100.0,
                dt_hours: 0.5,
            },
        );
        state = last.state;
    }
    for (i, want) in EXPECTED.iter().enumerate() {
        let got = state.v[i];
        let tol = 64.0 * f64::EPSILON * want.abs().max(1.0);
        assert!(
            (got - want).abs() <= tol,
            "component {i}: got {got} want {want} tol {tol}"
        );
    }
    assert!((last.methane_rate - 2.6735357834934597).abs() <= 1e-12);
    assert!((last.methane_fraction - 0.4386144934789377).abs() <= 1e-12);
    assert!((last.ph - 7.256418925816771).abs() <= 1e-12);
    assert!(last.inhibited);
}
